# SPDX-License-Identifier: MIT
# Trusted AF_UNIX observer for scm/notify fixtures (takeover root). Never runs
# the candidate; it only uses descriptors handed to it on stdin or files. Sockets come in
# as fd 0 because bash marks N<&FD close-on-exec for N > 2 when FD is (redir.c).
import array, ast, os, select, socket, stat, sys, time


def sk(fd):
    return socket.socket(fileno=int(fd))


def kind_of(mode):
    for test, name in ((stat.S_ISREG, 'regular'), (stat.S_ISSOCK, 'socket'), (stat.S_ISCHR, 'char'),
                       (stat.S_ISLNK, 'symlink'), (stat.S_ISFIFO, 'fifo'), (stat.S_ISDIR, 'directory')):
        if test(mode):
            return name
    return 'other'


def await_datagram(s):
    # select, not settimeout: a timeout would set O_NONBLOCK on the description shared with the shell.
    if not select.select([s], [], [], 5)[0]:
        raise SystemExit('no datagram within 5 s')


def main():
    cmd, args = sys.argv[1], sys.argv[2:]
    if cmd == 'info':
        # info FD LABEL [sockname|peer]
        s = sk(args[0])
        text = '%s family=%s type=%s' % (args[1], s.family.name, s.type.name)
        if args[2:] == ['sockname']:
            text += ' sockname=%r' % s.getsockname()
        elif args[2:] == ['peer']:
            text += ' peer=%r' % s.getpeername()
        print(text)
    elif cmd == 'send':
        sk(args[0]).send(ast.literal_eval(args[1]))
    elif cmd == 'drain':
        try:
            sk(args[0]).recv(64, socket.MSG_DONTWAIT)
            print('%s extra=yes' % args[1])
        except BlockingIOError:
            print('%s extra=no' % args[1])
    elif cmd in ('cloexec', 'inherited'):
        pid = args[0]
        for item in args[1:]:
            label, fd = item.split('=')
            if cmd == 'cloexec':
                with open('/proc/%s/fdinfo/%s' % (pid, fd)) as handle:
                    flags = [int(l.split()[1], 8) for l in handle if l.startswith('flags:')][0]
                print('%s cloexec=%s' % (label, 'yes' if flags & 0o2000000 else 'no'))
            else:
                target = os.readlink('/proc/%s/fd/%s' % (pid, fd))
                try:
                    mine = os.readlink('/proc/self/fd/%s' % fd)
                except OSError:
                    mine = None
                print('%s inherited=%s' % (label, 'yes' if mine == target else 'no'))
    elif cmd == 'sendto':
        s = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
        s.sendto(args[1].encode(), args[0])
        print('sent', args[1].encode())
    elif cmd == 'recv':
        r = sk(args[0])
        await_datagram(r)
        print('got', r.recv(64))
    elif cmd == 'recvfd':
        r = sk(args[0])
        await_datagram(r)
        body, anc, flags, _addr = r.recvmsg(8192, socket.CMSG_SPACE(4 * 4))
        fds = []
        for level, kind, data in anc:
            if level == socket.SOL_SOCKET and kind == socket.SCM_RIGHTS:
                fds.extend(array.array('i', data[:len(data) - len(data) % 4]))
        ref = os.stat(args[1])
        same = all((os.fstat(fd).st_dev, os.fstat(fd).st_ino) == (ref.st_dev, ref.st_ino) for fd in fds)
        print('body=%r fds=%d same-file=%s ctrunc=%s' % (body, len(fds), 'yes' if fds and same else 'no',
                                                       'yes' if flags & socket.MSG_CTRUNC else 'no'))
        for fd in fds:
            os.close(fd)
    elif cmd == 'sendfd':
        s, kind, body = sk(args[0]), args[1], args[2].encode()
        keep = None
        if kind.startswith('file:'):
            fd = os.open(kind[5:], os.O_RDONLY)
        elif kind == 'socket':
            keep = socket.socketpair(socket.AF_UNIX, socket.SOCK_DGRAM)
            fd = keep[0].fileno()
        elif kind == 'pty':
            fd = os.open('/dev/ptmx', os.O_RDWR | os.O_NOCTTY)
        else:
            raise SystemExit('unknown kind')
        s.sendmsg([body], [(socket.SOL_SOCKET, socket.SCM_RIGHTS, array.array('i', [fd]))])
        print('sent %s body=%r' % (kind.split(':')[0], body))
    elif cmd == 'fdkind':
        info = os.stat('/proc/%s/fd/%s' % (args[0], args[1]))
        print('received kind=%s' % kind_of(info.st_mode))
    elif cmd == 'samefile':
        a, b = os.stat('/proc/%s/fd/%s' % (args[0], args[1])), os.stat(args[2])
        print('received same-file=%s' % ('yes' if (a.st_dev, a.st_ino) == (b.st_dev, b.st_ino) else 'no'))
    elif cmd == 'stat':
        try:
            info = os.lstat(args[0])
        except FileNotFoundError:
            print('%s kind=absent' % args[0])
            return
        text = '%s kind=%s' % (args[0], kind_of(info.st_mode))
        if stat.S_ISLNK(info.st_mode):
            text += ' target=%r' % os.readlink(args[0])
        elif stat.S_ISREG(info.st_mode):
            text += ' mode=%04o content=%r' % (stat.S_IMODE(info.st_mode), open(args[0], 'rb').read())
        print(text)
    elif cmd == 'serve':
        # serve READYFIFO OUT NAME...: bind each name, report readiness, collect datagrams.
        ready, out, names = args[0], args[1], args[2:]
        socks = []
        for name in names:
            s = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
            s.bind(name.replace('\\0', '\0'))
            socks.append(s)
        with open(ready, 'w') as handle:
            handle.write('ready\n')
        got = {i: [] for i in range(len(socks))}
        deadline = time.monotonic() + 5
        first = None
        while time.monotonic() < deadline:
            limit = deadline if first is None else min(deadline, first + 0.3)
            readable, _, _ = select.select(socks, [], [], max(0, limit - time.monotonic()))
            if not readable:
                if first is not None:
                    break
                continue
            for s in readable:
                got[socks.index(s)].append(s.recv(65536))
                first = first or time.monotonic()
        with open(out, 'w') as handle:
            for i, name in enumerate(names):
                handle.write('%s datagrams=%d bodies=%r\n' % (name.replace('\\0', '@'), len(got[i]), got[i]))
    elif cmd == 'bound-then-closed':
        s = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
        s.bind(args[0])
        s.close()
        print('%s kind=%s' % (args[0], kind_of(os.lstat(args[0]).st_mode)))
    elif cmd == 'count':
        # count LOG NAME: number of NAME records since the last count; truncates LOG.
        with open(args[0]) as handle:
            n = sum(1 for line in handle if '"syscall": "%s"' % args[1] in line)
        open(args[0], 'w').close()
        print('%s-calls=%d' % (args[1], n))
    else:
        raise SystemExit('unknown command ' + cmd)


main()

