# SPDX-License-Identifier: MIT
# Trusted reader of system-seccomp.py JSON logs for sync fixtures (takeover root).
# segments LOG OPERAND...: split at openat of "seg-*.mark"; per segment, for each
# operand in order print the access modes of its openat calls and whether the next
# fsync and close (before the following operand's openat) name the same descriptor.
import json, sys

ACC = {0: 'RDONLY', 1: 'WRONLY', 2: 'RDWR'}


def main():
    log, operands = sys.argv[2], set(sys.argv[3:])
    records = [json.loads(line) for line in open(log)]
    segment, events = None, []
    for r in records:
        if r['syscall'] == 'openat' and r.get('string1', '').startswith('seg-') and r['string1'].endswith('.mark'):
            if segment:
                report(segment, events)
            segment, events = r['string1'][4:-5], []
        elif segment:
            events.append(r)
    if segment:
        report(segment, events)


def report(segment, events):
    print('== %s' % segment)
    current = None
    for r in events:
        if r['syscall'] == 'openat' and r.get('string1') in OPERANDS:
            if current is None or current['name'] != r['string1'] or current['fsync'] is not None:
                if current:
                    emit(current)
                current = {'name': r['string1'], 'modes': [], 'fsync': None, 'close': None}
            current['modes'].append(ACC.get(r['arg2'] & 3, '?'))
        elif current and r['syscall'] == 'fsync' and current['fsync'] is None:
            current['fsync'] = r['arg0']
        elif current and r['syscall'] == 'close' and current['fsync'] is not None and current['close'] is None:
            current['close'] = r['arg0']
    if current:
        emit(current)


def emit(c):
    if c['fsync'] is None:
        tail = 'fsync=none'
    else:
        tail = 'fsync-then-close=%s' % ('same-fd' if c['close'] == c['fsync'] and c['fsync'] > 2 else 'MISMATCH')
    print('%s open=%s %s' % (c['name'], ','.join(c['modes']), tail))


OPERANDS = set(sys.argv[3:])
main()

